// Backward compatibility aliases
export const INDMIRA_AGRO_CSV = INDMIRA_AGRO_DAILY_CSV;
export const US_DOE_BENCHMARK_CSV = US_DOE_DAILY_CSV;
export const KAGGLE_REAL_BOILER_CSV = KAGGLE_REAL_HOURLY_CSV;
export const SAMPLE_BOILER_CSV = INDMIRA_AGRO_DAILY_CSV;

export type CaseStudyType = 'INDMIRA' | 'US_DOE' | 'KAGGLE_REAL';
export type GranularityType = 'DAILY' | 'HOURLY';

export const getSampleDataset = (caseType: CaseStudyType, granularity: GranularityType): string => {
  if (caseType === 'INDMIRA') {
    return granularity === 'HOURLY' ? INDMIRA_AGRO_HOURLY_CSV : INDMIRA_AGRO_DAILY_CSV;
  }
  if (caseType === 'US_DOE') {
    return granularity === 'HOURLY' ? US_DOE_HOURLY_CSV : US_DOE_DAILY_CSV;
  }
  if (caseType === 'KAGGLE_REAL') {
    return granularity === 'HOURLY' ? KAGGLE_REAL_HOURLY_CSV : KAGGLE_REAL_DAILY_CSV;
  }
  return INDMIRA_AGRO_DAILY_CSV;
};
